function renderGenericModalFields(record, isEdit) {
  const config = TABLES_CONFIG[currentTableKey];
  const container = document.getElementById('generic-modal-fields');
  const recId = record.id || generateHexId(config.prefix);

  container.innerHTML = config.fields.map(f => {
    const val = record[f.key] !== undefined ? record[f.key] : "";

    if (f.type === "readonly") {
      return `
        <div>
          <label class="field-label">${f.label}</label>
          <input type="text" class="raw-input-box" id="modal-field-${f.key}" value="${recId}" readonly style="opacity:0.6; font-family:'JetBrains Mono';">
        </div>
      `;
    }

    if (f.type === "text") {
      return `
        <div>
          <label class="field-label">${f.label} ${f.required ? '<span style="color:var(--accent);">*</span>' : ''}</label>
          <input type="text" class="raw-input-box" id="modal-field-${f.key}" value="${val}">
        </div>
      `;
    }

    if (f.type === "textarea") {
      return `
        <div>
          <label class="field-label">${f.label} ${f.required ? '<span style="color:var(--accent);">*</span>' : ''}</label>
          <textarea class="raw-textarea-box" id="modal-field-${f.key}" style="min-height:70px;">${val}</textarea>
        </div>
      `;
    }

    if (f.type === "select") {
      let optsHTML = "";
      if (f.optionsSource === "containers") {
        optsHTML = availableContainers.map(c => `<option value="${c.id}" ${c.id === val ? 'selected' : ''}>${c.name}</option>`).join('');
      } else if (f.optionsSource === "themes_optional") {
        optsHTML = `<option value="">-- Root Level (No Parent) --</option>` +
                   availableThemes.filter(t => t.id !== recId).map(t => `<option value="${t.id}" ${t.id === val ? 'selected' : ''}>${t.name}</option>`).join('');
      } else if (f.optionsSource === "specifics") {
        optsHTML = availableSpecifics.map(s => `<option value="${s.id}" ${s.id === val ? 'selected' : ''}>${s.name} · ${s.container ? s.container.name : ''}</option>`).join('');
      }
      return `
        <div>
          <label class="field-label">${f.label}</label>
          <select class="raw-input-box" id="modal-field-${f.key}" style="height:44px;">
            ${optsHTML}
          </select>
        </div>
      `;
    }

    if (f.type === "json_array") {
      const arrVal = Array.isArray(val) ? val.join(', ') : val;
      return `
        <div>
          <label class="field-label">${f.label} (comma separated)</label>
          <input type="text" class="raw-input-box" id="modal-field-${f.key}" value="${arrVal}">
        </div>
      `;
    }

    if (f.type === "multi_select") {
      const activeIds = Array.isArray(val) ? val : [];
      let pills = "";
      if (f.optionsSource === "usages") {
        pills = availableUsages.map(u => {
          const active = activeIds.includes(u.id);
          return `
            <label style="display:inline-flex; align-items:center; gap:0.35rem; background:var(--bg-input); padding:0.35rem 0.65rem; border-radius:4px; font-size:0.8rem; cursor:pointer;">
              <input type="checkbox" class="modal-multi-chk-${f.key}" value="${u.id}" ${active ? 'checked' : ''}>
              <span>${u.icon || ''} ${u.name}</span>
            </label>
          `;
        }).join('');
      } else if (f.optionsSource === "themes") {
        pills = availableThemes.map(t => {
          const active = activeIds.includes(t.id);
          const parent = t.parent_name ? ` (${t.parent_name})` : '';
          return `
            <label style="display:inline-flex; align-items:center; gap:0.35rem; background:var(--bg-input); padding:0.35rem 0.65rem; border-radius:4px; font-size:0.8rem; cursor:pointer;">
              <input type="checkbox" class="modal-multi-chk-${f.key}" value="${t.id}" ${active ? 'checked' : ''}>
              <span>${t.child_of ? '↳ 🏷️' : '📁'} ${t.name}${parent}</span>
            </label>
          `;
        }).join('');
      }
      return `
        <div>
          <label class="field-label">${f.label}</label>
          <div style="display:flex; flex-wrap:wrap; gap:0.4rem; padding:0.5rem; background:var(--bg-card); border:1px solid var(--border-dim); border-radius:var(--radius-sm);">
            ${pills}
          </div>
        </div>
      `;
    }

