function renderSpecificBadge(s) {
  const badge = document.getElementById('specific-selected-val');
  const clearBtn = document.getElementById('specific-clear-btn');
  if (s) {
    const cname = s.container ? s.container.name : '';
    badge.innerHTML = `<span class="selected-val-badge">📍 ${s.name} · <span style="opacity:0.75; font-weight:normal;">${cname}</span></span>`;
    if (clearBtn) clearBtn.style.display = 'inline-flex';
  } else {
    badge.innerHTML = `<span style="color:var(--text-muted); font-size:0.9rem;">Select specific endpoint...</span>`;
    if (clearBtn) clearBtn.style.display = 'none';
  }
}

function filterSpecificDropdown(q) {
  const list = document.getElementById('specific-options-list');
  const createRow = document.getElementById('specific-create-row');
  const query = (q || "").trim().toLowerCase();

  const matches = availableSpecifics.filter(s => {
    const sName = (s.name || "").toLowerCase();
    const cName = (s.container && s.container.name) ? s.container.name.toLowerCase() : '';
    return sName.includes(query) || cName.includes(query);
  });

  if (matches.length === 0) {
    list.innerHTML = '<div style="color:var(--text-muted); font-size:0.85rem; padding:0.5rem;">No matching endpoints.</div>';
  } else {
    list.innerHTML = matches.map(s => {
      const isSelected = activeQuote.specific_id === s.id;
      const cname = (s.container && s.container.name) ? ` · ${s.container.name}` : '';
      return `
        <div class="dropdown-opt-row ${isSelected ? 'selected' : ''}" onclick="selectSpecific('${s.id}')">
          <div class="opt-label-group">
            <div class="opt-title-row">
              ${isSelected ? '<span class="opt-check">✓</span>' : ''}
              <span class="opt-title">${s.name}</span>
              <span class="opt-context">${cname}</span>
            </div>
          </div>
        </div>
      `;
    }).join('');
  }

  if (query && !availableSpecifics.some(s => (s.name || "").toLowerCase() === query)) {
    createRow.style.display = 'flex';
    document.getElementById('specific-create-query').textContent = q.trim();
  } else {
    createRow.style.display = 'none';
  }
}

function handleSpecificKey(e) {
  if (e.key === 'Enter') {
    const q = (document.getElementById('specific-search-input').value || "").trim();
    const match = availableSpecifics.find(s => (s.name || "").toLowerCase() === q.toLowerCase());
    if (match) selectSpecific(match.id);
    else openCreateSpecificModal(q);
  } else if (e.key === 'Escape') {
    closeAllDropdowns();
  }
}

