// ==============================================================================
// 4. DISPLAY / RENDER FUNCTION
// ==============================================================================
void renderQuote(const QuoteRenderPayload &q) {
  Serial.println("\n╔══════════════════════════════════════════════════════════════════════════╗");
  Serial.printf("║ QUOTE #%-4ld                                                              ║\n", q.idx);
  Serial.println("╠══════════════════════════════════════════════════════════════════════════╣");
  Serial.println(q.content);

  if (q.context.length() > 0) {
    Serial.println("\n--- Genesis Context ---");
    Serial.println(q.context);
  }

  Serial.println("──────────────────────────────────────────────────────────────────────────");
  Serial.printf("📍 Attribution: %s · %s\n", q.specificName.c_str(), q.containerName.c_str());

  if (q.effectiveDate.length() > 0) {
    Serial.printf("📅 Date:        %s\n", q.effectiveDate.c_str());
  }

  if (q.themeNames.length() > 0) {
    Serial.printf("🏷️ Themes:      %s\n", q.themeNames.c_str());
  }
  Serial.println("╚══════════════════════════════════════════════════════════════════════════╝\n");

  // Output to E-Paper display, TFT LCD, or I2S DAC speaker here!
}

