// ==============================================================================
// 4. DISPLAY / RENDER FUNCTION (CLEAN E-PAPER SPECIFICATION)
// ==============================================================================
void renderQuote(const QuoteRenderPayload &q) {
  Serial.println("\n┌──────────────────────────────────────────────────────────────────────────┐");
  // Header: Clean #IDX and Date (No 'QUOTE' or 'TURSO CLOUD EDGE')
  Serial.printf("│ #%-4ld                                                     %12s │\n", q.idx, q.effectiveDate.c_str());
  Serial.println("├──────────────────────────────────────────────────────────────────────────┤");

  // Content: Wrapped in quotation marks “...”
  Serial.printf("│ “%s”\n", q.content.c_str());

  if (q.context.length() > 0) {
    Serial.printf("│\n│ [%s]\n", q.context.c_str());
  }

  Serial.println("├──────────────────────────────────────────────────────────────────────────┤");
  // Footer: Container on LEFT of Specific · Tags prefixed with '#'
  String attribution = q.containerName + " · " + q.specificName;

  // Format tags with '#'
  String tagsFormatted = "";
  if (q.themeNames.length() > 0) {
    int start = 0;
    while (start < q.themeNames.length()) {
      int comma = q.themeNames.indexOf(',', start);
      if (comma == -1) comma = q.themeNames.length();
      String tag = q.themeNames.substring(start, comma);
      tag.trim();
      if (tag.length() > 0) {
        if (tagsFormatted.length() > 0) tagsFormatted += " ";
        tagsFormatted += "#" + tag;
      }
      start = comma + 1;
    }
  }

  Serial.printf("│ %-36s  %32s │\n", attribution.c_str(), tagsFormatted.c_str());
  Serial.println("└──────────────────────────────────────────────────────────────────────────┘\n");

  // Output to physical E-Paper display (GxEPD2) or TFT LCD here!
}

