147	               "q.idx, "
148	               "q.main_content AS content, "
149	               "COALESCE(q.context, '') AS context, "
150	               "COALESCE(NULLIF(q.date, ''), s.date, '') AS effective_date, "
151	               "COALESCE(s.name, '') AS specific_name, "
152	               "COALESCE(c.name, '') AS container_name, "
153	               "COALESCE((SELECT GROUP_CONCAT(t.name, ', ') FROM themes t WHERE t.id IN (SELECT value FROM json_each(q.theme_ids))), '') AS theme_names "
154	               "FROM quotes q "
155	               "LEFT JOIN specifics s ON q.specific_id = s.id "
156	               "LEFT JOIN containers c ON s.container_id = c.id ";
