  --ep-qmark: #0284c7;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.15);
}
.epaper-chassis:not(.inverted).palette-gold {
  --ep-bg: #fefce8;
  --ep-border: #fde68a;
  --ep-text: #1c1917;
  --ep-accent: #b45309;
  --ep-dim: #78716c;
  --ep-tag-bg: #fef3c7;
  --ep-tag-border: #fcd34d;
  --ep-tag-text: #92400e;
  --ep-qmark: #b45309;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.15);
}
.epaper-chassis:not(.inverted).palette-mono {
  --ep-bg: #f2efe9;
  --ep-border: #cccccc;
  --ep-text: #050505;
  --ep-accent: #050505;
  --ep-dim: #777777;
  --ep-tag-bg: #e4e1d9;
  --ep-tag-border: #c9c5ba;
  --ep-tag-text: #555555;
  --ep-qmark: #888888;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.15);
}

/* Compact 2.9" aspect ratio simulation */
.epaper-chassis.compact {
  max-width: 540px;
  padding: 1.5rem 1.75rem;
}

