  // Header components: #<idx> ~ <specific> on left, Date: <date> on right
  const headerTitleHTML = `<strong class="ep-idx-num" style="color:${idxColor};">#${b.idx}</strong><span class="ep-sep">~</span><span class="ep-specific-title" style="color:${specificColor};">${b.specificName}</span>`;
  const headerDateHTML = `<span class="ep-date-label">Date: </span><span class="ep-date-val" style="color:${dateColor};">${b.effectiveDate}</span>`;

  // Footer components: Tags on LEFT (subtle low-contrast blocks), Container on RIGHT
  const tagStyle = accentTargets.tags ? '' : 'style="background:#111 !important; border-color:#262626 !important; color:#6a6a6a !important;"';
  const tagsBlocks = b.hashtagThemes.map(t => `<span class="ep-tag-block" ${tagStyle}>${t}</span>`).join('');
  const containerHTML = `<span class="ep-container-name" style="color:${containerColor};">${b.containerName}</span>`;

  if (currentSubLayout === 'minimal') {
    stage.innerHTML = `
      <div class="ep-type-minimal">
        <!-- 1. Header: #<idx> ~ <specific> on left, Date: <date> on right -->
