void renderQuote(const QuoteRenderPayload &q) {
  Serial.println("\n┌──────────────────────────────────────────────────────────────────────────┐");
  // Header: #<idx> ~ <specific> on left · Date: <date> on right
  String headerLeft = "#" + String(q.idx) + " ~ " + q.specificName;
  String headerRight = "Date: " + q.effectiveDate;
  Serial.printf("│ %-44s  %24s │\n", headerLeft.c_str(), headerRight.c_str());
  Serial.println("├──────────────────────────────────────────────────────────────────────────┤");

  // Category alignment rule: writing => justify, music / poem => left
  bool isWriting = q.category.equalsIgnoreCase("writing") || q.category.equalsIgnoreCase("bài viết");
  Serial.printf("│ (Category: %s -> %s)\n", q.category.c_str(), isWriting ? "JUSTIFY" : "LEFT-ALIGN");

  // Content: Italic-feel wrapped in distinct framing quotation marks “...”
  Serial.printf("│ “%s”\n", q.content.c_str());

  if (q.context.length() > 0) {
    Serial.printf("│\n│ [%s]\n", q.context.c_str());
  }

  Serial.println("├──────────────────────────────────────────────────────────────────────────┤");
  // Footer: Tags on LEFT (prefixed with '#', muted blocks) · Container on RIGHT
  String tagsFormatted = "";
  if (q.themeNames.length() > 0) {
    int start = 0;
    while (start < q.themeNames.length()) {
      int comma = q.themeNames.indexOf(',', start);
      if (comma == -1) comma = q.themeNames.length();
      String tag = q.themeNames.substring(start, comma);
      tag.trim();
      if (tag.length() > 0) {
        if (tagsFormatted.length() > 0) tagsFormatted += " ";
        tagsFormatted += "#" + tag;
      }
      start = comma + 1;
    }
  }

  Serial.printf("│ %-36s  %32s │\n", tagsFormatted.c_str(), q.containerName.c_str());
  Serial.println("└──────────────────────────────────────────────────────────────────────────┘\n");

  // Output to physical E-Paper display (GxEPD2) or TFT LCD here!
}

