// ==============================================================================
// VISION COLOR ENGINE:
// - Quotation mark & Container: SAME color, chosen randomly from pool of 2 [Gold (#f59e0b) vs Blue (#38bdf8)]
// - Each tag: distinct random color for variety
// - Header (#IDX ~ Specific, Date: <date>): Ghost (#666666) & smaller
// ==============================================================================

// Deterministic pseudo-random seed based on quote index or ID so it feels stable per quote
const quoteSeed = (typeof b.idx === 'number' ? b.idx : (parseInt(String(b.idx).replace(/\D/g, ''), 10) || 1)) + reRollSeed;
let sharedAccentColor;
if (sharedColorMode === 'gold') {
  sharedAccentColor = '#f59e0b';
} else if (sharedColorMode === 'blue') {
  sharedAccentColor = '#38bdf8';
} else {
  const isGold = (quoteSeed % 2 === 0);
  sharedAccentColor = isGold ? '#f59e0b' : '#38bdf8'; // Random pool of 2 (Gold vs Blue)
}

// Content: Italic and wrapped by distinct quotation marks matching the Container's color
const formattedContent = `<span class="ep-qmark ep-qmark-open" style="color:${sharedAccentColor} !important;">“</span><em>${b.content.replace(/\n/g, '<br>')}</em><span class="ep-qmark ep-qmark-close" style="color:${sharedAccentColor} !important;">”</span>`;

// Header components: Ghost (#666) and smaller font size
const headerTitleHTML = `<span class="ep-header-left"><strong class="ep-idx-num">#${b.idx}</strong><span class="ep-sep">~</span><span class="ep-specific-title">${b.specificName}</span></span>`;
const headerDateHTML = `<span class="ep-header-right"><span class="ep-date-label">Date: </span><span class="ep-date-val">${b.effectiveDate}</span></span>`;

// Dynamic Tag Color Palette Pool for individual tags
const tagColorPool = [
  { bg: '#081724', border: '#12395b', text: '#38bdf8' }, // Sapphire Blue
  { bg: '#1c1507', border: '#423211', text: '#f59e0b' }, // Imperial Gold
  { bg: '#07181c', border: '#113e4a', text: '#06b6d4' }, // Cyan
  { bg: '#071811', border: '#11422c', text: '#10b981' }, // Emerald
  { bg: '#1a080f', border: '#4a1529', text: '#f43f5e' }, // Crimson Rose
  { bg: '#16091e', border: '#431959', text: '#c084fc' }, // Violet
  { bg: '#191307', border: '#473611', text: '#fbbf24' }  // Amber
];

// Each tag receives an individual random color block from the palette
const tagsBlocks = b.hashtagThemes.map((t, idx) => {
  // String hash for stable color selection per tag name
  let hash = 0;
  for (let i = 0; i < t.length; i++) hash = (hash << 5) - hash + t.charCodeAt(i);
  const colorIdx = Math.abs((hash + idx * 7) % tagColorPool.length);
  const c = tagColorPool[colorIdx];

