// ==============================================================================
// VAST INDEPENDENT COLOR ENGINE FOR TAGS (INFINITE 360° SPECTRUM POOL)
// - Each tag computes an independent random hue using Golden Ratio distribution
// - Completely separate from the 2-color Gold/Blue pool of quotes & container
// ==============================================================================
function generateVastTagStyle(tagName, tagIndex) {
  // Independent hash for this specific tag string
  let hash = 0;
  for (let i = 0; i < tagName.length; i++) {
    hash = ((hash << 5) - hash) + tagName.charCodeAt(i);
    hash |= 0;
  }

  // Golden ratio hue stepping (137.508°) ensures neighboring tags have wildly distinct hues
  const goldenAngle = 137.508;
  const hue = Math.abs(Math.floor((hash * goldenAngle + tagIndex * 89 + reRollSeed) % 360));

  if (isInverted) {
    // High-contrast dark E-Paper mode: deep quiet capsule + bright pastel/neon text
    const textColor   = `hsl(${hue}, 85%, 72%)`;
    const borderColor = `hsla(${hue}, 70%, 40%, 0.45)`;
    const bgColor     = `hsla(${hue}, 65%, 8%, 0.9)`;
    return `background: ${bgColor} !important; border-color: ${borderColor} !important; color: ${textColor} !important;`;
  } else {
    // Light authentic paper mode: soft tinted capsule + deep rich ink text
    const textColor   = `hsl(${hue}, 85%, 26%)`;
    const borderColor = `hsla(${hue}, 55%, 65%, 0.6)`;
    const bgColor     = `hsla(${hue}, 60%, 93%, 0.95)`;
    return `background: ${bgColor} !important; border-color: ${borderColor} !important; color: ${textColor} !important;`;
  }
}

